const items = $input.first().json.items;
const today = new Date().toISOString().slice(0, 10);

// 중복 방지
const staticData = $getWorkflowStaticData('global');
if (staticData.lineupSentDate === today) {
  return [{ json: { found: false, reason: "이미 발송됨" } }];
}

// 오늘 오전 9시 기준
const nineAM = new Date();
nineAM.setHours(9, 0, 0, 0);

const lineupArticle = items.find(item => {
  // 1. pubDate가 오늘인지 + 오전 9시 이후인지
  const pubDate = new Date(item.pubDate);
  if (pubDate < nineAM) return false;
  if (pubDate.toISOString().slice(0, 10) !== today) return false;

  // 2. description에 "선발 라인업" + 포지션 키워드 포함 여부
  const desc = item.description.replace(/<[^>]*>/g, '');
  const hasLineup = desc.includes("선발 라인업");
  const hasPosition = desc.includes("중견수") || desc.includes("우익수") || desc.includes("좌익수") || desc.includes("포수");

  const isKBO = item.link.includes('kbaseball') || item.originallink.includes('kbaseball');
  return hasLineup && hasPosition && isKBO;
});

if (!lineupArticle) {
  return [{ json: { found: false, reason: "라인업 기사 없음" } }];
}

// 발송 기록 저장
staticData.lineupSentDate = today;

return [{
  json: {
    found: true,
    title: lineupArticle.title.replace(/<[^>]*>/g, ''),
    link: lineupArticle.link,
    originallink: lineupArticle.originallink,
    description: lineupArticle.description.replace(/<[^>]*>/g, ''),
  }
}];

const html = $input.first().json.data;
const MY_TEAM = "한화";

// HTML 태그 제거
const text = html
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();

// 포지션 목록
const positions = ['중견수', '우익수', '좌익수', '지명타자', '1루수', '2루수', '3루수', '포수', '유격수'];

// "한화는 X(포지션) Y(포지션)... 순으로" 패턴 찾기
const posPattern = positions.map(p => `[가-힣A-Za-z]+\\(${p}\\)`).join('[\\s,]*');
const fullPattern = new RegExp(`한화[는이가]?\\s*(${posPattern}[\\s,가-힣A-Za-z()]*?)\\s*순으로`);

const match = text.match(fullPattern);

if (!match) {
  return [{ json: { found: false, reason: "라인업 패턴 매칭 실패" } }];
}

// 선수명(포지션) 개별 추출
const lineupRaw = match[0];
const players = [...lineupRaw.matchAll(/([가-힣A-Za-z]+)\((중견수|우익수|좌익수|지명타자|1루수|2루수|3루수|포수|유격수)\)/g)];

if (players.length < 8) {
  return [{ json: { found: false, reason: `선수 파싱 부족 (${players.length}명)` } }];
}

// 선발투수 따로 추출
const pitcherMatch = text.match(/선발투수\s*(?:로\s*)?([가-힣]+?)(?:가|이)?\s*(?:등판|역투)/);
const pitcher = pitcherMatch ? pitcherMatch[1] : '미확인';

const lineupFormatted = players.map((p, i) => 
  `${i+1}번 ${p[2]}: ${p[1]}`
).join('\n');

return [{
  json: {
    found: true,
    lineup: lineupFormatted,
    pitcher,
    link: $('Code in JavaScript1').item.json.link,
    title: $('Code in JavaScript1').item.json.title,
  }
}];
